using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var rows=new List<object>();
 foreach(var local in new[]{false,true})foreach(var worldModule in new[]{false,true})foreach(var force in new[]{false,true})foreach(var euler in new[]{Vector3.zero,new Vector3(-90,0,0),new Vector3(23,47,11)})foreach(var scale in new[]{Vector3.one,Vector3.one*1.3f,new Vector3(1,2,3)}){
 var go=new GameObject("module-frame-probe"){hideFlags=HideFlags.HideAndDontSave};try{go.transform.rotation=Quaternion.Euler(euler);go.transform.localScale=scale;var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.startSpeed=0;main.startLifetime=10;main.simulationSpace=local?ParticleSystemSimulationSpace.Local:ParticleSystemSimulationSpace.World;main.scalingMode=ParticleSystemScalingMode.Hierarchy;var em=ps.emission;em.enabled=false;var sh=ps.shape;sh.enabled=false;if(force){var f=ps.forceOverLifetime;f.enabled=true;f.space=worldModule?ParticleSystemSimulationSpace.World:ParticleSystemSimulationSpace.Local;f.x=1;f.y=3;f.z=2;}else{var v=ps.velocityOverLifetime;v.enabled=true;v.space=worldModule?ParticleSystemSimulationSpace.World:ParticleSystemSimulationSpace.Local;v.x=1;v.y=3;v.z=2;}ps.useAutoRandomSeed=false;ps.randomSeed=17;ps.Play();ps.Pause();ps.Emit(1);var steps=new List<object>();for(int i=1;i<=12;i++){ps.Simulate(1f/60,false,false,false);var p=new ParticleSystem.Particle[1];ps.GetParticles(p);var a=p[0];var w=local?go.transform.TransformPoint(a.position):a.position;steps.Add(new{frame=i,position=new[]{a.position.x,a.position.y,a.position.z},world=new[]{w.x,w.y,w.z},velocity=new[]{a.velocity.x,a.velocity.y,a.velocity.z}});}rows.Add(new{local,worldModule,force,euler=new[]{euler.x,euler.y,euler.z},scale=new[]{scale.x,scale.y,scale.z},steps});}finally{UnityEngine.Object.DestroyImmediate(go);}}
 File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,unityVersion=Application.unityVersion,dt=1f/60,rows}));return "Module frame cases="+rows.Count;
 }
}
